"""Bilinear coarse-to-fine placement on matching direct-quad block charts.

Only free fine vertices move. Boundary samples, profile pins, topology and
semantic identities remain the fine construction's own data. Coarse positions
are addressed by exact integer chart identities, never spatial proximity in
the street plane. Missing identities reject the transfer. This is an initial
placement primitive; it does not certify the resulting quads or heights.
"""
import bpy
from . import curved_junction_nodes as boundary
c=boundary.c


def build():
    name='Prochitecture Streets / Cyclic quad chart prolongation v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for key in ('Fine','Coarse','Mouths'):g.socket(key,'NodeSocketGeometry')
    for key in ('Fine Rows','Fine Radial','Coarse Rows','Coarse Radial'):g.socket(key,'NodeSocketInt')
    g.socket('Input Valid','NodeSocketBool')
    g.socket('Geometry','NodeSocketGeometry','OUTPUT');g.socket('Valid','NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');fine=inp.outputs['Fine'];coarse=inp.outputs['Coarse'];mouths=inp.outputs['Mouths']
    n=c.V(g,inp.outputs['Fine Rows']);m=c.V(g,inp.outputs['Fine Radial'])
    N=c.V(g,inp.outputs['Coarse Rows']);M=c.V(g,inp.outputs['Coarse Radial'])
    sides=c._count(g,mouths);H=N*.5;a=M*.5;b=N-a
    choose=lambda flag,x,y,kind='FLOAT':c.choose(g,flag,x,y,kind)
    eq=lambda x,y:g.math('COMPARE',x,y)
    maximum=lambda x,y:g.math('MAXIMUM',x,y)
    minimum=lambda x,y:g.math('MINIMUM',x,y)
    chart,row,col=[g.math('ROUND',v) for v in g.separate(c.named(g,'st_cq_key','FLOAT_VECTOR'))]
    band=g.math('GREATER_THAN',chart,.5);guide=eq(chart,0.)
    spoke=eq(chart,-1.);hub=eq(chart,-2.)
    center=g.math('LESS_THAN',chart,-2.5)*g.math('GREATER_THAN',chart,-3.-sides+.5)
    interior=g.math('LESS_THAN',chart,-3.-sides+.5)*g.math('GREATER_THAN',chart,-3.-2.*sides+.5)
    seam=g.math('LESS_THAN',chart,-3.-2.*sides+.5)*g.math('GREATER_THAN',chart,-3.-3.*sides+.5)
    owner=choose(band,chart-1.,choose(guide+spoke,row,choose(hub,0.,
        choose(center,-3.-chart,choose(interior,-3.-sides-chart,-3.-2.*sides-chart)))))
    block=choose(interior,g.math('FLOOR',row/262144.),choose(eq(row,2.),1.,0.))
    packed=g.math('MODULO',row,262144.)
    wi=choose(interior,g.math('FLOOR',packed/(m*.5+1.)),
              choose(eq(row,0.)+eq(row,3.),m*.5,col))
    wj=choose(interior,g.math('MODULO',packed,m*.5+1.),choose(eq(row,0.),col,m*.5))
    cols=choose(eq(block,0.),a,b)
    ni=choose(band+guide,N,choose(center+spoke+hub,H,cols))
    nj=choose(band,M,choose(guide,0.,choose(center+spoke+hub,H,a)))
    i=choose(band,row*N/n,choose(guide,col*N/n,choose(center,row*N/n,
        choose(spoke+hub,H,wi*cols/choose(eq(block,0.),m*.5,n-m*.5)))))
    j=choose(band,col*M/m,choose(guide,0.,choose(center+spoke,col*N/n,
        choose(hub,H,wj*M/m))))
    i=minimum(maximum(i,0.),ni);j=minimum(maximum(j,0.),nj)
    lo=g.math('FLOOR',i);bottom=g.math('FLOOR',j)
    hi=minimum(lo+1.,ni);top=minimum(bottom+1.,nj);u=i-lo;v=j-bottom

    def guide_key(owner,r):
        last=eq(r,N)
        return g.xyz(0.,choose(last,g.math('MODULO',owner+1.,sides),owner),choose(last,0.,r))

    def center_key(owner,i,j):
        previous=g.math('MODULO',owner+sides-1.,sides)
        key=g.xyz(-3.-owner,i,j)
        key=choose(eq(j,H),g.xyz(-1.,previous,i),key,'VECTOR')
        key=choose(eq(i,H),g.xyz(-1.,owner,j),key,'VECTOR')
        key=choose(eq(i,H)*eq(j,H),g.xyz(-2.,0.,0.),key,'VECTOR')
        key=choose(eq(i,0.),guide_key(previous,N-j),key,'VECTOR')
        return choose(eq(j,0.),guide_key(owner,i),key,'VECTOR')

    def wedge_key(owner,i,j):
        first=eq(block,0.);second=eq(block,1.);third=eq(block,2.)
        i0=eq(i,0.);i1=eq(i,cols);j0=eq(j,0.);j1=eq(j,a)
        seam_chart=-3.-2.*sides-owner
        key=g.xyz(-3.-sides-owner,block*262144.+i*(a+1.)+j,0.)
        # Same precedence as the direct three-block taper builder.
        key=choose(first*i1+second*i0,g.xyz(seam_chart,0.,j),key,'VECTOR')
        key=choose(first*j1,g.xyz(seam_chart,1.,i),key,'VECTOR')
        key=choose(third*i0,g.xyz(seam_chart,1.,a-j),key,'VECTOR')
        key=choose(second*j1+third*j0,g.xyz(seam_chart,2.,i),key,'VECTOR')
        outer=(first+second)*j0;isguide=first*i0+third*j1;mouth=(second+third)*i1
        local_row=choose(first,choose(outer,i,j),choose(mouth,N,a+i))
        column=choose(first,choose(outer,0.,M),choose(second,j,a+j))
        border=maximum(outer,maximum(isguide,mouth));tip=border*eq(local_row,0.)
        reverse=1.-eq(c._read(g,mouths,'st_cj_half',owner,'INT'),-1.)
        global_row=choose(reverse,N-local_row,local_row)
        core=maximum(tip,maximum(isguide,mouth*eq(column,M)))
        edge_key=choose(core,guide_key(owner,global_row),g.xyz(owner+1.,global_row,column),'VECTOR')
        key=choose(border,edge_key,key,'VECTOR')
        at_hub=first*i1*j1+second*i0*j1+third*i0*j0
        return choose(at_hub,g.xyz(seam_chart,3.,0.),key,'VECTOR')

    def key(i,j):
        band_key=choose(eq(j,M),guide_key(owner,i),g.xyz(owner+1.,i,j),'VECTOR')
        return choose(band,band_key,choose(guide,guide_key(owner,i),
            choose(center+spoke+hub,center_key(owner,i,j),wedge_key(owner,i,j),'VECTOR'),'VECTOR'),'VECTOR')

    # Nearest lookup occurs in exact INTEGER ID space. Check equality before
    # using its value, so an absent identity cannot borrow a nearby vertex.
    keyed=c._store(g,coarse,'_prolong_position',g.position(),'FLOAT_VECTOR')
    coarse_key=g.xyz(*[g.math('ROUND',x) for x in g.separate(c.named(g,'st_cq_key','FLOAT_VECTOR'))])
    keyed=g.setpos(keyed,coarse_key)
    position=[0.,0.];matched=1.
    for I,J,weight in ((lo,bottom,(1.-u)*(1.-v)),(hi,bottom,u*(1.-v)),
                       (lo,top,(1.-u)*v),(hi,top,u*v)):
        wanted=key(I,J)
        nearest=g.node('GeometryNodeSampleNearest','Exact coarse quad chart identity');nearest.domain='POINT'
        g.bind(keyed,nearest.inputs['Geometry']);g.bind(wanted,nearest.inputs['Sample Position'])
        at=nearest.outputs['Index']
        found=c._sample(g,keyed,g.position(),at,'FLOAT_VECTOR')
        error=[x-y for x,y in zip(g.separate(found),g.separate(wanted))]
        equal=g.math('LESS_THAN',sum(g.math('ABSOLUTE',x) for x in error),.1)
        matched=matched*equal
        point=c._vec(g,c._sample(g,keyed,c.named(g,'_prolong_position','FLOAT_VECTOR'),at,'FLOAT_VECTOR'))
        position=c._add(position,c._scale(point,weight))
    fixed=c.named(g,'st_cq_fixed','BOOLEAN')
    good=maximum(fixed,matched*(band+guide+spoke+hub+center+interior+seam))
    valid=c.V(g,inp.outputs['Input Valid'])*g.math('GREATER_THAN',c._count(g,coarse),0.)*c._stat(g,fine,good)
    valid=valid*g.math('GREATER_THAN',n,1.)*g.math('GREATER_THAN',m,1.)
    valid=valid*g.math('GREATER_THAN',N,M*.5)*g.math('COMPARE',g.math('MODULO',N,2.),0.)
    valid=valid*g.math('GREATER_THAN',M,1.)*g.math('COMPARE',g.math('MODULO',M,2.),0.)
    proposed=c._pick(g,fixed,c._vec(g,g.position()),position)
    result=g.setpos(fine,g.xyz(*proposed))
    out=g.node('NodeGroupOutput');g.bind(boundary._empty(g,result,valid),out.inputs['Geometry']);g.bind(valid,out.inputs['Valid'])
    return g.g
